WITH deleted_process_events AS (
    DELETE FROM public.skill_trigger_rule_process_events
    WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND rule_key = #{ruleKey}
    RETURNING 1
),
deleted_skill_events AS (
    DELETE FROM public.skill_trigger_rule_skill_events
    WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND rule_key = #{ruleKey}
    RETURNING 1
),
deleted_result_events AS (
    DELETE FROM public.skill_trigger_rule_result_events
    WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND rule_key = #{ruleKey}
    RETURNING 1
),
deleted_lifecycle_events AS (
    DELETE FROM public.skill_trigger_rule_lifecycle_events
    WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND rule_key = #{ruleKey}
    RETURNING 1
),
deleted_status_events AS (
    DELETE FROM public.skill_trigger_rule_status_events
    WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND rule_key = #{ruleKey}
    RETURNING 1
),
deleted_health_events AS (
    DELETE FROM public.skill_trigger_rule_health_threshold_events
    WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND rule_key = #{ruleKey}
    RETURNING 1
),
deleted_internal_state_events AS (
    DELETE FROM public.skill_trigger_rule_internal_state_events
    WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND rule_key = #{ruleKey}
    RETURNING 1
),
deleted_subject_events AS (
    DELETE FROM public.skill_trigger_rule_subject_events
    WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND rule_key = #{ruleKey}
    RETURNING 1
),
deleted_condition_groups AS (
    DELETE FROM public.skill_trigger_rule_condition_groups
    WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND rule_key = #{ruleKey}
    RETURNING 1
),
deleted_actions AS (
    DELETE FROM public.skill_trigger_rule_actions
    WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND rule_key = #{ruleKey}
    RETURNING 1
),
deleted_cooldowns AS (
    DELETE FROM public.skill_trigger_rule_per_target_cooldowns
    WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND rule_key = #{ruleKey}
    RETURNING 1
)
